function hasLetterLoop(grid: string[][]): boolean {
  const R = grid.length, C = grid[0].length;
  const parent = new Int32Array(R * C).fill(-2); // -2 = not visited
  const dirs = [[1, 0], [-1, 0], [0, 1], [0, -1]];
  for (let s = 0; s < R * C; s++) {
    if (parent[s] !== -2) continue;
    parent[s] = -1;
    const queue = [s];
    for (let qi = 0; qi < queue.length; qi++) {
      const u = queue[qi], r = Math.floor(u / C), c = u % C;
      for (const [dr, dc] of dirs) {
        const nr = r + dr, nc = c + dc;
        if (nr < 0 || nc < 0 || nr >= R || nc >= C || grid[nr][nc] !== grid[r][c]) continue;
        const v = nr * C + nc;
        if (v === parent[u]) continue;
        if (parent[v] !== -2) return true;
        parent[v] = u;
        queue.push(v);
      }
    }
  }
  return false;
}

