class Solution:
    def hasLetterLoop(self, grid: List[List[str]]) -> bool:
        R, C = len(grid), len(grid[0])
        parent = [-2] * (R * C)  # -2 = not visited
        for s in range(R * C):
            if parent[s] != -2:
                continue
            parent[s] = -1
            queue = deque([s])
            while queue:
                u = queue.popleft()
                r, c = divmod(u, C)
                for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
                    if not (0 <= nr < R and 0 <= nc < C) or grid[nr][nc] != grid[r][c]:
                        continue
                    v = nr * C + nc
                    if v == parent[u]:
                        continue
                    if parent[v] != -2:
                        return True
                    parent[v] = u
                    queue.append(v)
        return False

