function hasLetterLoop(grid: string[][]): boolean {
  const R = grid.length, C = grid[0].length;
  const root = Array.from({ length: R * C }, (_, i) => i);
  const find = (x: number): number => {
    while (root[x] !== x) { root[x] = root[root[x]]; x = root[x]; }
    return x;
  };
  const join = (a: number, b: number): boolean => { // false if already connected
    const ra = find(a), rb = find(b);
    if (ra === rb) return false;
    root[ra] = rb;
    return true;
  };
  for (let r = 0; r < R; r++) {
    for (let c = 0; c < C; c++) {
      const u = r * C + c;
      if (c + 1 < C && grid[r][c + 1] === grid[r][c] && !join(u, u + 1)) return true;
      if (r + 1 < R && grid[r + 1][c] === grid[r][c] && !join(u, u + C)) return true;
    }
  }
  return false;
}

